window {
    margin: 0;
    border: 1px solid #3b4a4d;
    border-radius: 16px;
    background-color: #111719;
    color: #e8efed;
    font-family: "Noto Sans", sans-serif;
    font-size: 14px;
}

#outer-box {
    padding: 18px;
}

#input {
    margin: 0 0 16px;
    padding: 12px 14px;
    border: 1px solid #304144;
    border-radius: 10px;
    background-color: #1b2527;
    color: #f4faf8;
    caret-color: #73d0b0;
}

#input:focus {
    border-color: #73d0b0;
    box-shadow: 0 0 0 1px #73d0b0;
}

#inner-box {
    margin: 0;
}

#scroll {
    margin: 0;
}

#entry {
    min-width: 112px;
    min-height: 92px;
    margin: 4px;
    padding: 10px 6px;
    border: 1px solid transparent;
    border-radius: 11px;
    background-color: transparent;
}

#entry:hover,
#entry:selected {
    border-color: #426d64;
    background-color: #203332;
    color: #ffffff;
}

#entry:selected {
    box-shadow: inset 0 -2px 0 #73d0b0;
}

#img {
    margin: 2px 0 8px;
}

#text {
    color: #dce8e4;
}

#entry:selected #text {
    color: #ffffff;
}

